import csv
import json
import subprocess
import sys
import time
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path


UCSC = "https://api.genome.ucsc.edu"
CHAIN_URL = "https://hgdownload.soe.ucsc.edu/goldenPath/hg19/liftOver/hg19ToHg38.over.chain.gz"


def install_pyliftover():
    subprocess.check_call(
        [sys.executable, "-m", "pip", "install", "--no-deps", "--target", ".deps", "pyliftover==0.4.1"]
    )
    sys.path.insert(0, str(Path(".deps").resolve()))


def fetch_json(url, retries=5):
    last = None
    for attempt in range(retries):
        try:
            with urllib.request.urlopen(url, timeout=30) as response:
                return json.loads(response.read().decode("utf-8"))
        except Exception as exc:
            last = exc
            time.sleep(1.5 * (attempt + 1))
    raise last


def ucsc_seq(genome, chrom, zero_start, zero_end):
    params = urllib.parse.urlencode(
        {"genome": genome, "chrom": chrom, "start": int(zero_start), "end": int(zero_end)}
    )
    data = fetch_json(f"{UCSC}/getData/sequence?{params}")
    return data.get("dna", "").upper()


def base_at_one_based(genome, chrom, pos_one_based, length):
    if pos_one_based is None or pos_one_based < 1:
        return ""
    return ucsc_seq(genome, chrom, pos_one_based - 1, pos_one_based - 1 + length)


def download_chain(path):
    if path.exists():
        return
    with urllib.request.urlopen(CHAIN_URL, timeout=120) as response:
        path.write_bytes(response.read())


def read_snps(path):
    with open(path, newline="") as handle:
        reader = csv.DictReader(handle, delimiter="\t")
        rows = []
        for row in reader:
            row["start"] = int(row["start"])
            rows.append(row)
    return rows


def main():
    in_tsv, out_txt = sys.argv[1], sys.argv[2]
    install_pyliftover()
    from pyliftover import LiftOver

    chain_path = Path("hg19ToHg38.over.chain.gz")
    download_chain(chain_path)
    lo = LiftOver(str(chain_path))
    rows = read_snps(in_tsv)

    modes = {
        "hg19_1based": [],
        "hg19_0based_start": [],
        "hg38_1based": [],
        "hg38_0based_start": [],
        "hg19_1based_lifted_to_hg38": [],
    }
    examples = {name: [] for name in modes}
    lifted_positions = []

    for row in rows:
        chrom, start, ref = row["chr"], row["start"], row["ref"].upper()
        length = len(ref)
        tests = {}
        tests["hg19_1based"] = base_at_one_based("hg19", chrom, start, length)
        tests["hg19_0based_start"] = base_at_one_based("hg19", chrom, start + 1, length)
        tests["hg38_1based"] = base_at_one_based("hg38", chrom, start, length)
        tests["hg38_0based_start"] = base_at_one_based("hg38", chrom, start + 1, length)
        converted = lo.convert_coordinate(chrom, start - 1)
        if converted:
            best = converted[0]
            lifted_chrom, lifted_zero, strand, _score = best
            lifted_one = int(lifted_zero) + 1
            lifted_positions.append((chrom, start, lifted_chrom, lifted_one, strand))
            tests["hg19_1based_lifted_to_hg38"] = base_at_one_based(
                "hg38", lifted_chrom, lifted_one, length
            )
        else:
            lifted_positions.append((chrom, start, None, None, None))
            tests["hg19_1based_lifted_to_hg38"] = ""

        for name, observed in tests.items():
            ok = observed == ref and "N" not in ref
            modes[name].append(ok)
            if not ok and len(examples[name]) < 8:
                examples[name].append(
                    {
                        "chr": chrom,
                        "start": start,
                        "ref": ref,
                        "observed": observed,
                        "alt": row["alt"],
                        "label": row["label"],
                    }
                )

    with open(out_txt, "w") as out:
        out.write("coordinate_diagnostic\n")
        out.write(f"n_rows\t{len(rows)}\n")
        for name, values in modes.items():
            out.write(f"{name}_matches\t{sum(values)}\n")
            out.write(f"{name}_mismatches\t{len(values) - sum(values)}\n")
        out.write("\nfirst_mismatches\n")
        for name in modes:
            out.write(f"{name}\t{json.dumps(examples[name], sort_keys=True)}\n")
        out.write("\nfirst_lifted_positions\n")
        for item in lifted_positions[:12]:
            out.write("\t".join("" if x is None else str(x) for x in item) + "\n")


if __name__ == "__main__":
    main()

